import * as THREE from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Set position from scenePosition
  group.position.set(0, 1, 0.06);

  // Create plane geometry for the card
  const planeGeometry = new THREE.PlaneGeometry(2.0, 1.25);

  // Load brushed-metal texture
  const metalTexture = ctx.textureLoader.load(
    config.assets?.imageUrl || '/prism-assets/chrome/brushed-metal.map.png'
  );
  metalTexture.colorSpace = THREE.SRGBColorSpace;

  // Create material using TSL nodes
  const colorNode = textureNode(metalTexture);
  const planeMaterial = new THREE.MeshBasicNodeMaterial({
    colorNode,
  });

  // Create and add plane mesh
  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(planeMesh);

  // Create text using fontAtlas
  const textObj = ctx.fontAtlas.createText('Collection 2', {
    fontSize: 0.34,
    fontFamily: 'Lora',
    fontWeight: 400,
    color: config.colors?.ink || '#16161d',
    align: 'center',
  });

  if (textObj) {
    textObj.position.z = 0.01;
    group.add(textObj);
  }

  // Cleanup function
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();
    metalTexture.dispose();
  };

  // Event handlers
  group.userData.handlers = {};

  return group;
}
